	key := b.graph.client.create(b.data)!
	if key == '' {
		return NotFoundError{
			table: 'gadgets'
		}
	}
	return b.graph.gadgets_by_keys([key])![0]
}

// exec inserts the row and its edges, in one transaction.
pub fn (b GadgetCreate) exec() ! {
	b.graph.client.create(b.data)!
}

// GadgetCreateBulk builds the insert of several `gadgets` rows. Start one with
// `Graph.gadgets().create_bulk()`.
pub struct GadgetCreateBulk {
	graph Graph
pub:
	builders []GadgetCreate
}

// create_bulk starts the insert of the rows `builders` describe.
pub fn (q GadgetQuery) create_bulk(builders ...GadgetCreate) GadgetCreateBulk {
	return GadgetCreateBulk{
		graph:    q.graph
		builders: builders
	}
}

// map_create_bulk starts the insert of one row for each of `items`, which
// `configure` describes.
pub fn (q GadgetQuery) map_create_bulk[T](items []T, configure fn (GadgetCreate, T) GadgetCreate) GadgetCreateBulk {
	return q.create_bulk(...items.map(configure(q.create(), it)))
}

// update_new_values sets what a conflict on `on_conflict_columns` does: the stored row takes the values of the create, but for immutable ones.
// It needs a vgraph driver.
pub fn (b GadgetCreateBulk) update_new_values() GadgetCreateBulk {
	return GadgetCreateBulk{
		...b
		builders: b.builders.map(it.update_new_values())
	}
}

// ignore sets what a conflict on `on_conflict_columns` does: the stored row stays as it is, and `save` returns it.
// It needs a vgraph driver.
pub fn (b GadgetCreateBulk) ignore() GadgetCreateBulk {
	return GadgetCreateBulk{
		...b
		builders: b.builders.map(it.ignore())
	}
}

// do_nothing sets what a conflict on `on_conflict_columns` does: the stored row stays as it is, and `save` leaves it out.
// It needs a vgraph driver.
pub fn (b GadgetCreateBulk) do_nothing() GadgetCreateBulk {
	return GadgetCreateBulk{
		...b
		builders: b.builders.map(it.do_nothing())
	}
}

// on_conflict_columns makes each create an upsert, when a row conflicts with a
// stored one on `columns`, which a unique index or the key must cover.
pub fn (b GadgetCreateBulk) on_conflict_columns(columns ...string) GadgetCreateBulk {
	return GadgetCreateBulk{
		...b
		builders: b.builders.map(it.on_conflict_columns(...columns))
	}
}

// save inserts the rows and their edges, in one transaction, and returns them,
// read back, in order. With `do_nothing`, the rows that conflict are left out.
pub fn (b GadgetCreateBulk) save() ![]GadgetNode {
	keys := b.graph.client.create_bulk(b.builders.map(it.data))!
	return b.graph.gadgets_by_keys(keys.filter(it != ''))
}

// exec inserts the rows and their edges, in one transaction.
pub fn (b GadgetCreateBulk) exec() ! {
	b.graph.client.create_bulk(b.builders.map(it.data))!
}

