// GadgetUpdate builds the update of the `gadgets` rows that match its conditions,
// and of their edges. Start one with `Graph.gadgets().update()`.
pub struct GadgetUpdate {
	graph Graph
pub:
	data vgraph.MutationData
}

// update starts the update of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q GadgetQuery) update() GadgetUpdate {
	return GadgetUpdate{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .update
			table: 'gadgets'
			conds: q.query.conds.clone()
		}
	}
}

