// exec updates the rows and their edges, in one transaction, and returns how
// many there were.
pub fn (b GadgetUpdate) exec() !int {
	return b.graph.client.update(b.data)
}

// GadgetDeleteOne builds the delete of one `gadgets` row. Start one with
// `Graph.gadgets().delete_one(node)` or `delete_one_id(id)`.
pub struct GadgetDeleteOne {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete_one starts the delete of the row of `node`.
pub fn (q GadgetQuery) delete_one(node GadgetNode) GadgetDeleteOne {
	return q.delete_one_id(node.gadget.id)
}

// delete_one_id starts the delete of the row with the key `id`.
pub fn (q GadgetQuery) delete_one_id(id i64) GadgetDeleteOne {
	return GadgetDeleteOne{
		graph: q.graph
		data:  vgraph.MutationData{
			op:      .delete_one
			table:   'gadgets'
			row_key: id.str()
		}
	}
}

// exec deletes the row, with its join table rows, in one transaction, or
// returns a `NotFoundError`.
pub fn (b GadgetDeleteOne) exec() ! {
	if !b.graph.client.delete_one(b.data)! {
		return NotFoundError{
			table: 'gadgets'
		}
	}
}

// GadgetDelete builds the delete of the `gadgets` rows that match its conditions.
// Start one with `Graph.gadgets().delete()`.
pub struct GadgetDelete {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete starts the delete of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q GadgetQuery) delete() GadgetDelete {
	return GadgetDelete{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .delete
			table: 'gadgets'
			conds: q.query.conds.clone()
		}
	}
}

// where keeps the rows that match every one of `conds`.
pub fn (b GadgetDelete) where(conds ...load.Cond) GadgetDelete {
	return GadgetDelete{
		...b
		data: b.data.with_conds(conds)
	}
}

