// exec deletes the rows, with their join table rows, in one transaction, and
// returns how many there were.
pub fn (b GadgetDelete) exec() !int {
	return b.graph.client.delete(b.data)
}

// gadgets_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) gadgets_by_keys(keys []string) ![]GadgetNode {
	// as stored: no privacy rule or interceptor hides a row just written
	rows := Graph{
		client: g.client.bypass()
	}.gadgets().where(load.in_keys('id', keys, .i64)).all()!
	mut by_key := map[string]GadgetNode{}
	for row in rows {
		by_key[row.gadget.id.str()] = row
	}
	mut found := []GadgetNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'gadgets'
			}
		}
	}
	return found
}

